--liquibase formatted sql

--changeset arkana:004-seed-catalog
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:0 select count(*) from public.tarot_cards
-- BEGIN GENERATED CATALOG DATA
-- Generated from arkana-web/src/data and arkana-web/src/i18n.ts.
insert into public.tarot_cards (
  id,
  card_number,
  suit,
  name_pt_br,
  name_en,
  description_pt_br,
  description_en,
  light_pt_br,
  light_en,
  shadow_pt_br,
  shadow_en
)
values
  ('the-fool', 0, 'major', 'O Louco', 'The Fool', 'O Louco caminha leve diante do desconhecido. Sua imagem fala de liberdade, confiança e disponibilidade para começar sem controlar todos os passos.', 'A traveler walks leisurely with only the clothes on his back and a light bundle. He holds a white rose, celebrating freedom, yet does not notice that there is no road ahead. This card represents freedom and the unknown state of not knowing what comes next.', 'Espontaneidade, abertura e coragem para experimentar. Um novo ciclo pode nascer quando a curiosidade é maior que o medo.', 'Pure values free from preconceived notions, convention, or worldly judgment. By living according to one''s own heart, unexpected opportunities and new ideas may emerge.', 'Impulsividade, dispersão ou fuga de responsabilidade. A liberdade perde força quando não existe presença para perceber os riscos.', 'Passive indecision stands out. Aimless drifting may bring loneliness, irresponsibility, and loss of trust from those around you.'),
  ('the-magician', 1, 'major', 'O Mago', 'The Magician', 'O Mago reúne os quatro elementos sobre a mesa e direciona sua vontade. Ele representa recursos disponíveis, intenção clara e capacidade de realização.', 'A young man confidently raises a wand, ready to demonstrate his skill. On the table before him are the four elements: wand, pentacle, sword, and cup. This card announces that everything is prepared, and the time to act has arrived.', 'Iniciativa, habilidade e comunicação consciente. Há condições para transformar uma ideia em ação concreta.', 'Clear awareness of what you want to do. There is no need to wait for support or preparation from others; you take initiative.', 'Manipulação, excesso de confiança ou talento mal direcionado. A aparência de domínio pode esconder preparo insuficiente.', 'Confused reasoning for your actions and true confidence may not yet exist. Can also indicate misuse of talent or ability to deceive others.'),
  ('the-high-priestess', 2, 'major', 'A Sacerdotisa', 'The High Priestess', 'A Sacerdotisa permanece entre o visível e o oculto. Ela convida ao silêncio, à observação e ao conhecimento que amadurece internamente.', 'A mysterious woman crowned with the earth mother''s crown sits between black and white pillars, holding the Torah. Her pure and noble bearing radiates wisdom, reason, and spiritual calm.', 'Intuição, receptividade e leitura sutil da situação. Nem toda resposta precisa ser forçada ou revelada imediatamente.', 'Approaching matters with innate wisdom and reason / a noble spirit that remains impartial', 'Passividade, segredos ou desconexão da própria percepção. O silêncio pode virar distância quando impede uma conversa necessária.', 'Only seeing what you want to see / perfectionism and judgment becoming too prominent'),
  ('the-empress', 3, 'major', 'A Imperatriz', 'The Empress', 'A Imperatriz expressa criação, abundância e cuidado. Tudo ao seu redor sugere crescimento alimentado por presença e sensibilidade.', 'The Empress sits comfortably in abundant nature. Her full figure suggests pregnancy, growth, unconditional love, and the endless cycle of life.', 'Fertilidade de ideias, prazer, acolhimento e expansão natural. O que recebe atenção consistente tende a florescer.', 'Enjoying abundant blessings / naturally receiving love, beauty, wealth, and growth', 'Excesso de proteção, apego ao conforto ou doação sem limites. Cuidar do outro não deve significar abandonar a si.', 'Tiring of excessive blessings / losing gratitude and becoming lazy or dependent'),
  ('the-emperor', 4, 'major', 'O Imperador', 'The Emperor', 'O Imperador ocupa um lugar de estrutura e autoridade. Sua força está em estabelecer limites, direção e sustentação para o que precisa durar.', 'The Emperor sits upon his throne in armor, ruling as a sovereign. He represents ambition, leadership, responsibility, and the power to stabilize a group.', 'Organização, estabilidade e liderança responsável. Decisões firmes criam um terreno seguro para avançar.', 'Establishing lasting stability / leading effectively and fulfilling your responsibility', 'Rigidez, controle ou resistência a perspectivas diferentes. A estrutura se torna prisão quando não consegue se adaptar.', 'Using force for temporary stability / ruling harshly and eroding trust'),
  ('the-hierophant', 5, 'major', 'O Hierofante', 'The Hierophant', 'O Hierofante transmite saberes consolidados e valores compartilhados. Ele representa tradição, aprendizado e pertencimento a uma estrutura maior.', 'The Hierophant holds a triple cross and blesses two priests. He teaches morality, tradition, and the way to live, becoming a spiritual guide and trusted symbol.', 'Orientação, estudo e compromisso com princípios. Uma referência experiente ou método conhecido pode oferecer clareza.', 'Building trust and bonds through ethics, tradition, forgiveness, and faith', 'Dogmatismo, conformidade automática ou dependência de aprovação. Uma regra antiga pode já não responder ao momento atual.', 'Violating ethics / misusing trust and bonds for selfish purposes'),
  ('the-lovers', 6, 'major', 'Os Enamorados', 'The Lovers', 'Os Enamorados falam de vínculo, escolha e alinhamento de valores. A união representada na carta também exige responsabilidade pelo que se escolhe.', 'A man and woman in Eden are blessed by an angel. Their nakedness shows fearlessness, attraction, joy, and complete satisfaction.', 'Conexão autêntica, reciprocidade e decisões coerentes com o coração. Relações crescem quando existe presença e verdade.', 'Experiencing happiness as if in a dream / drawn toward joy created with another', 'Indecisão, projeção ou conflito entre desejo e valores. Evitar uma escolha também produz consequências.', 'Indulging in immediate pleasure / choosing comfort without accepting consequences'),
  ('the-chariot', 7, 'major', 'O Carro', 'The Chariot', 'O Carro avança ao integrar forças que apontam para direções diferentes. Sua mensagem é de movimento conduzido por foco e autodisciplina.', 'A warrior rides a chariot drawn by black and white sphinxes. Controlling them requires strong will, power, and unwavering action toward the goal.', 'Determinação, conquista e capacidade de manter o rumo. Energia bem direcionada reduz a distância até o objetivo.', 'Boldly confronting obstacles / advancing toward your goal with strong momentum', 'Pressa, competitividade ou tentativa de controlar tudo. Movimento sem integração interna pode levar ao desgaste.', 'Unable to control yourself / power spirals out of control and rushes in the wrong direction'),
  ('strength', 8, 'major', 'A Força', 'Strength', 'A Força mostra poder sem violência: a presença serena transforma o impulso bruto. É a coragem que nasce do domínio de si.', 'A gentle woman softly touches the jaw of a fierce lion. This card represents not physical force, but the inner strength of love, patience, and mutual understanding.', 'Paciência, confiança e firmeza gentil. A situação pede consistência emocional mais do que confronto.', 'Overcoming difficulty / moving another through love, patience, and sincerity', 'Repressão, insegurança ou reação desproporcional. Forçar uma demonstração de poder pode revelar fragilidade.', 'Unable to endure and letting go / losing patience before reaching the end'),
  ('the-hermit', 9, 'major', 'O Eremita', 'The Hermit', 'O Eremita ilumina apenas o próximo passo. Ele representa recolhimento consciente, investigação e sabedoria construída pela experiência.', 'An old man in a grey robe stands alone with a lantern. He withdraws from the world to face his inner truth and seek wisdom from past experience.', 'Discernimento, autonomia e tempo para ouvir a própria verdade. A pausa pode organizar o que o ruído confundiu.', 'Seeking ideals / quietly examining your inner world and gaining wisdom', 'Isolamento, fechamento ou excesso de análise. A busca interior perde sentido quando impede o retorno ao mundo.', 'Not facing reality / clinging to past glory and withdrawing from the world'),
  ('wheel-of-fortune', 10, 'major', 'A Roda da Fortuna', 'Wheel of Fortune', 'A Roda da Fortuna recorda que ciclos mudam e nenhuma posição permanece fixa. O movimento traz encontros, viradas e novas condições.', 'The giant wheel turns slowly, surrounded by symbolic beings. All life exists within an inescapable current where one may rise or fall.', 'Oportunidade, sincronicidade e abertura para uma mudança favorável. Flexibilidade ajuda a aproveitar o novo ciclo.', 'Events improve through fate''s flow / unexpected chances appear and must be seized quickly', 'Instabilidade, repetição inconsciente ou sensação de falta de controle. Resistir ao movimento pode aumentar a turbulência.', 'Being toyed with by fate / things deteriorate, chances are wasted, and confusion mounts'),
  ('justice', 11, 'major', 'A Justiça', 'Justice', 'A Justiça observa causa e consequência com clareza. Ela pede equilíbrio, honestidade e responsabilidade pelas escolhas realizadas.', 'A calm judge sits with scales and sword, objectively weighing cause and effect. This card shows fairness, judgment, and balance without emotional interference.', 'Discernimento, decisões justas e alinhamento entre intenção e ação. Os fatos ganham força quando vistos sem distorção.', 'Responding calmly without emotion / facts receive fair evaluation', 'Julgamento rígido, negação de responsabilidade ou desequilíbrio. A necessidade de ter razão pode impedir uma avaliação honesta.', 'Swayed by emotion and responding unfairly / imbalance and unjust treatment'),
  ('the-hanged-man', 12, 'major', 'O Enforcado', 'The Hanged Man', 'O Enforcado suspende a ação para enxergar de outro ângulo. Sua aparente imobilidade contém entrega, revisão e mudança de perspectiva.', 'A man hangs upside down from a tree, yet his expression is peaceful and his head glows. Because his body cannot move, his thoughts become clearer.', 'Pausa fértil, desapego e compreensão renovada. Soltar uma expectativa pode revelar uma saída antes invisível.', 'Facing your situation and thinking clearly / accepting what cannot be changed', 'Estagnação, sacrifício sem propósito ou adiamento. Esperar deixa de ser sabedoria quando evita uma decisão possível.', 'Unable to accept your state and struggling / suffering increases through resistance'),
  ('death', 13, 'major', 'A Morte', 'Death', 'A Morte representa encerramento e transformação inevitável. Algo precisa perder sua forma atual para que outra realidade possa surgir.', 'Death rides a white horse across the battlefield as the sun rises in the distance. This represents not only an end, but also rebirth and movement to a new stage.', 'Renovação, liberação e coragem para concluir um ciclo. O fim abre espaço quando é reconhecido com honestidade.', 'Moving to a new stage / accepting an ending and embracing new beginnings', 'Apego, medo da mudança ou tentativa de prolongar o que já terminou. Resistência pode tornar a transição mais dolorosa.', 'Bound by the past and unable to progress / clinging to the current state prolongs suffering'),
  ('temperance', 14, 'major', 'A Temperança', 'Temperance', 'A Temperança combina elementos distintos até encontrar uma nova medida. Ela fala de integração, cura gradual e ritmo sustentável.', 'An angel skillfully pours water between two cups, as if suggesting communication. This card emphasizes mixing, adjustment, and the new results born from different elements meeting.', 'Equilíbrio, conciliação e capacidade de ajustar extremos. Pequenas mudanças consistentes produzem uma transformação profunda.', 'Accepting new things / opening your heart and adapting to different perspectives and values', 'Excesso, impaciência ou dificuldade de encontrar medida. Misturar tudo sem critério também pode diluir o que é essencial.', 'Unable to accept different things / rejecting others'' input and causing friction'),
  ('the-devil', 15, 'major', 'O Diabo', 'The Devil', 'O Diabo ilumina desejos, dependências e acordos que limitam a liberdade. As correntes parecem firmes, mas também revelam onde existe escolha.', 'A naked man and woman are chained before the Devil, yet the chains are loose. The card shows the mind captured by desire and pleasure rather than the body.', 'Consciência dos próprios impulsos, vitalidade e coragem para encarar a sombra. Nomear o vínculo é o início da libertação.', 'Losing to the devil within / consumed by temptation and desire', 'Compulsão, apego, manipulação ou prazer que cobra um preço alto. Negar a dependência fortalece aquilo que aprisiona.', 'Fighting the devil within / attempting to control desire and cut unhealthy bonds'),
  ('the-tower', 16, 'major', 'A Torre', 'The Tower', 'A Torre rompe uma estrutura que já não consegue sustentar a verdade. A mudança é intensa, mas expõe o que estava oculto.', 'Lightning strikes the tower and the crown falls. The scene depicts shocking transformation, unforeseen accident, and destruction that clears the way for something new.', 'Revelação, libertação e reconstrução sobre bases mais honestas. O colapso pode encerrar uma falsa segurança.', 'A sudden shock arrives / the current situation changes instantly', 'Crise, resistência ao inevitável ou repetição de estruturas frágeis. Agarrar-se ao que cai amplia o impacto.', 'A shock that arrives gradually afterward / tension and collapse extend gradually'),
  ('the-star', 17, 'major', 'A Estrela', 'The Star', 'A Estrela surge depois da tempestade como sinal de esperança e reconexão. Sua nudez representa verdade, confiança e simplicidade.', 'A naked woman pours water under shining stars. The bright star has long guided travelers and represents ideals, hope, purity, and emerging talent.', 'Inspiração, cura e fé tranquila no caminho. Existe espaço para sonhar novamente sem negar a realidade.', 'Moving toward a bright future / following hope with confidence that you are on the right path', 'Desânimo, idealização ou perda de conexão com o propósito. Esperança sem cuidado concreto pode virar espera passiva.', 'Nothing materializes and everything drifts away / hope turns to disappointment'),
  ('the-moon', 18, 'major', 'A Lua', 'The Moon', 'A Lua ilumina um território de imagens, instintos e incerteza. Nem tudo é o que parece quando medos e intuições se misturam.', 'The sorrowful Moon shines over a dim landscape where visibility is poor. Dogs, a wolf, and a crayfish suggest anxiety rising from the unconscious.', 'Sensibilidade, imaginação e atenção ao mundo interno. Caminhar devagar permite distinguir percepção de projeção.', 'Viewing reality through illusion / uncertainty, anxiety, secrets, and unclear outlines', 'Confusão, ansiedade, autoengano ou informação incompleta. Decisões definitivas podem precisar esperar por mais clareza.', 'Gradually seeing through to reality / illusions fade as dawn approaches'),
  ('the-sun', 19, 'major', 'O Sol', 'The Sun', 'O Sol expõe, aquece e devolve vitalidade. Sua luz fala de verdade compartilhada, alegria e confiança para ocupar o próprio lugar.', 'The Sun shines in a clear sky over a naked child on a horse. This card represents the joy of being alive, vitality, growth, and future success.', 'Clareza, sucesso, entusiasmo e expressão autêntica. O que estava em dúvida pode finalmente ser visto.', 'Efforts bearing fruit / openly enjoying success and the joy of living', 'Excesso de exposição, otimismo ingênuo ou necessidade de reconhecimento. Brilhar não exige apagar os limites.', 'Unable to see sunlight / insufficient vitality and stunted growth'),
  ('judgement', 20, 'major', 'O Julgamento', 'Judgement', 'O Julgamento anuncia um chamado para despertar e responder ao que já não pode ser ignorado. O passado é revisto para liberar um novo posicionamento.', 'An angel blows a trumpet and the dead rise from their coffins. What was thought finished comes back to life, bringing a decisive opportunity.', 'Renascimento, compreensão e decisão alinhada com um propósito maior. A experiência pode ser integrada sem continuar definindo o futuro.', 'Seizing a fleeting opportunity / releasing what was once sealed away', 'Autocrítica, negação do chamado ou apego à culpa. Julgar-se continuamente impede a transformação que já está disponível.', 'Delaying until things freeze again / missing the chance through hesitation'),
  ('the-world', 21, 'major', 'O Mundo', 'The World', 'O Mundo encerra uma jornada com integração e plenitude. As partes encontram lugar dentro de uma visão mais ampla.', 'A dancer within a wreath holds wands and is surrounded by the four elemental beings. This card shows a completed world after a long journey.', 'Conclusão, realização e pertencimento. Um ciclo amadureceu e pode ser celebrado antes do próximo começo.', 'Achieving your goal and gaining satisfaction / savoring joy before the next stage', 'Pendências, dificuldade de concluir ou busca de perfeição. Reconhecer o que já foi alcançado é parte do fechamento.', 'Withdrawing because results are unsatisfying / completion falls short of expectation'),
  ('ace-of-cups', 1, 'cups', 'Ás de Copas', 'Ace of Cups', 'Esta carta combina um começo concentrado e cheio de potencial com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The Ace of Cups depicts the hand of God offering a cup brimming with water. The flowing water symbolizes love, emotion, and spiritual blessing. This card represents the beginning of profound emotional fulfillment and spiritual abundance.', 'Uma semente está pronta para receber direção. Os sentimentos podem circular com mais honestidade e receptividade.', 'Love and happiness overflow. The heart brims with love and joy, and emotions flow naturally. This card signals the emergence of new affection, tender connection, and a beginning that nourishes the soul.', 'O impulso inicial pode ser desperdiçado ou reprimido. Carências, idealizações ou emoções represadas pedem atenção.', 'Emotional exhaustion and unmet longing. Feelings cannot flow freely, leaving the heart hollow or yearning. It may also indicate suppressed affection, difficulty expressing love openly, or disappointed hopes.'),
  ('two-of-cups', 2, 'cups', 'Dois de Copas', 'Two of Cups', 'Esta carta combina uma escolha entre forças que buscam equilíbrio com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A man and woman exchange cups and gaze at each other sincerely. Above them appears a symbol of blessing, suggesting emotional alignment and a bond formed through mutual acceptance.', 'Comparar caminhos com presença favorece uma decisão mais íntegra. Os sentimentos podem circular com mais honestidade e receptividade.', 'Two hearts draw together and unite. Feelings harmonize, allowing a balanced and mutual connection. This card points to emotional union in romance, friendship, or partnership.', 'Indecisão ou polarização podem manter a situação suspensa. Carências, idealizações ou emoções represadas pedem atenção.', 'The relationship loses balance and gradually grows distant. Feelings no longer align, and misunderstanding, separation, or difficulty facing each other honestly may emerge.'),
  ('three-of-cups', 3, 'cups', 'Três de Copas', 'Three of Cups', 'Esta carta combina crescimento que nasce do encontro e da expressão com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'Three women raise their cups together in celebration. Fruits and flowers surround them, depicting joy shared with companions and the happiness of belonging to a community.', 'Colaboração e expansão tornam o movimento mais fértil. Os sentimentos podem circular com mais honestidade e receptividade.', 'Sharing joy with companions. Success and happiness are celebrated with friends, allies, or a group. This card points to mutual blessings, celebration, and heartfelt exchange.', 'Excesso, ruído ou falta de alinhamento podem dispersar resultados. Carências, idealizações ou emoções represadas pedem atenção.', 'Indulging in pleasure until restraint is lost. Excessive celebration or socializing leads to imbalance. It can also suggest cliques, gossip, or outward liveliness masking inner emptiness.'),
  ('four-of-cups', 4, 'cups', 'Quatro de Copas', 'Four of Cups', 'Esta carta combina uma estrutura que oferece estabilidade e contenção com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A person sits beneath a tree with folded arms, ignoring the cup offered by a mysterious hand. Three cups stand before them, yet their heart remains unmoved. This card depicts emotional stagnation and dissatisfaction.', 'Consolidar o que funciona cria base para o próximo passo. Os sentimentos podem circular com mais honestidade e receptividade.', 'Growing weary of the present and sinking into stagnation. Interest fades in what is before you, and even with options available, contentment remains elusive. This card suggests boredom, hesitation, and emotional withdrawal.', 'Controle e acomodação podem transformar segurança em estagnação. Carências, idealizações ou emoções represadas pedem atenção.', 'Beginning to notice an overlooked opportunity again. You slowly awaken from stagnation and start seeing the chances you once disregarded. It can also show a refreshed perspective and willingness to embrace new possibilities.'),
  ('five-of-cups', 5, 'cups', 'Cinco de Copas', 'Five of Cups', 'Esta carta combina uma tensão que revela perda, contraste ou necessidade de mudança com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A person in a black cloak gazes downward at spilled cups, while two cups still stand upright behind. The card shows grief from loss, yet reminds that not everything has been lost.', 'O desconforto mostra com clareza o que precisa ser reorganizado. Os sentimentos podem circular com mais honestidade e receptividade.', 'Immersed in grief because of a loss. The heart is consumed by what is gone and cannot yet see the possibilities that remain. This card suggests disappointment, regret, and emotional pain.', 'Fixar-se na falta pode impedir a percepção dos recursos restantes. Carências, idealizações ou emoções represadas pedem atenção.', 'Turning from grief and beginning to glimpse hope again. You slowly lift your head and recognize the hope that still remains. It can also mean accepting the loss and beginning emotional healing.'),
  ('six-of-cups', 6, 'cups', 'Seis de Copas', 'Six of Cups', 'Esta carta combina um movimento de ajuste, troca e recomposição com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'Children exchange cups filled with flowers in a peaceful town. The card evokes nostalgia, innocence, cherished memories, and the warmth of the past.', 'Reciprocidade e transição consciente restauram o fluxo. Os sentimentos podem circular com mais honestidade e receptividade.', 'Finding warmth in innocent memories. Memories of the past, pure feelings, or familiar people and places bring comfort. This card also suggests reunion, childhood, nostalgia, and kindness.', 'Desequilíbrio nas trocas ou apego ao passado atrasam a passagem. Carências, idealizações ou emoções represadas pedem atenção.', 'Bound by the past and unable to move forward. Overindulgence in what has been makes it hard to face the present. It can also point to immaturity, escapism, or old attachments becoming a burden.'),
  ('seven-of-cups', 7, 'cups', 'Sete de Copas', 'Seven of Cups', 'Esta carta combina um teste de discernimento, posicionamento e persistência com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'Seven cups float in the clouds, each holding a different vision. The figure gazes at them in confusion, suggesting many desires, illusions, and choices that have not yet taken shape in reality.', 'Escolher com critério fortalece a direção já conquistada. Os sentimentos podem circular com mais honestidade e receptividade.', 'Immersed in dreams and abundant possibilities. Imagination is active and countless options appear before you, though not all can become reality. This card suggests dreams, temptation, confusion, and desires not yet grounded in reality.', 'Defensividade, fantasia ou avaliação superficial confundem prioridades. Carências, idealizações ou emoções represadas pedem atenção.', 'Waking from fantasy and seeing reality clearly. You begin to emerge from unrealistic dreams and recognize which choices are truly workable. It can also mean making a decision and ceasing to escape from reality.'),
  ('eight-of-cups', 8, 'cups', 'Oito de Copas', 'Eight of Cups', 'Esta carta combina uma fase de movimento, prática e reorganização com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A person leaves behind eight cups and walks toward the mountains under the moon. Although much has already been built, the heart still seeks something more meaningful.', 'Repetição consciente e foco aceleram o aprendizado. Os sentimentos podem circular com mais honestidade e receptividade.', 'Leaving behind what no longer fulfills you. In search of deeper meaning, you choose to walk away from a familiar environment or relationship. This card suggests farewell, turning away, and a spiritual quest.', 'Automatismo, pressa ou aprisionamento mental estreitam possibilidades. Carências, idealizações ou emoções represadas pedem atenção.', 'Unable to leave and remaining where you are. Even when you know the current situation no longer fulfills you, you still hesitate to move. It may also point to avoiding a parting, delaying a decision, or being unable to let go.'),
  ('nine-of-cups', 9, 'cups', 'Nove de Copas', 'Nine of Cups', 'Esta carta combina um estágio de maturidade, autonomia e quase conclusão com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A satisfied person sits before nine arranged cups. Their posture conveys confidence, contentment, and the fulfillment of personal wishes.', 'A experiência acumulada permite reconhecer valor e suficiência. Os sentimentos podem circular com mais honestidade e receptividade.', 'A wish is fulfilled and satisfaction follows. What you longed for comes true, bringing joy and contentment. This card suggests enjoying your reward, happiness, and self-affirmation.', 'Isolamento, excesso de expectativa ou vigilância impedem descanso. Carências, idealizações ou emoções represadas pedem atenção.', 'Excessive self-satisfaction that loses touch with genuine joy. Things may appear satisfying on the surface while the heart feels hollow. It can also suggest vanity, greed, or pursuing pleasure solely for yourself.'),
  ('ten-of-cups', 10, 'cups', 'Dez de Copas', 'Ten of Cups', 'Esta carta combina a culminação de um ciclo e suas consequências com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A family raises their arms beneath a rainbow of ten cups. The card depicts emotional completeness, family happiness, and the joy of sharing blessings with loved ones.', 'O resultado pode ser integrado, compartilhado e transformado em legado. Os sentimentos podem circular com mais honestidade e receptividade.', 'Experiencing deep emotional fulfillment and shared happiness. A relationship reaches wholeness, and happiness is shared with family, a partner, or important loved ones. This card suggests peace, harmony, and a life filled with blessings.', 'Sobrecarga ou apego ao resultado dificultam o encerramento necessário. Carências, idealizações ou emoções represadas pedem atenção.', 'Disharmony appears beneath the image of happiness. Things may look happy outwardly while conflict or imbalance exists underneath. It can also suggest family pressure, emotional gaps, or shattered expectations.'),
  ('page-of-cups', 11, 'cups', 'Pajem de Copas', 'Page of Cups', 'Esta carta combina uma curiosidade jovem que traz notícia, estudo e descoberta com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A young page holds a cup from which a fish appears. The image suggests innocent imagination, emotional messages, and a heart open to wonder.', 'Abertura para aprender renova a relação com o tema. Os sentimentos podem circular com mais honestidade e receptividade.', 'Receiving emotional messages with an innocent heart. You receive feelings or inspiration with softness and purity. This card suggests confessions, messages, creativity, and delicate sensitivity.', 'Imaturidade ou informação incompleta pedem verificação antes de agir. Carências, idealizações ou emoções represadas pedem atenção.', 'Immature emotions that are easily unsettled. Feelings have not fully matured and are easily swayed by mood or fantasy. It can also point to escapism, childishness, or unstable emotional expression.'),
  ('knight-of-cups', 12, 'cups', 'Cavaleiro de Copas', 'Knight of Cups', 'Esta carta combina uma força em movimento que persegue sua intenção com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A knight rides calmly with a cup in hand, as if delivering an emotional invitation. This card shows romance, ideals, and movement guided by the heart.', 'Compromisso e ação colocam a energia do naipe em circulação. Os sentimentos podem circular com mais honestidade e receptividade.', 'Approaching your goal with romantic ideals. You move things forward through gentleness, ideals, and emotion. This card suggests confessions, invitations, creative inspiration, and romantic action.', 'Pressa, insistência ou intensidade sem escuta podem criar desequilíbrio. Carências, idealizações ou emoções represadas pedem atenção.', 'Immersed in fantasy and lacking real action. Too much indulgence in dreams or emotion leaves too little follow-through. It may also suggest indecision, sweet talk, or unreliable promises.'),
  ('queen-of-cups', 13, 'cups', 'Rainha de Copas', 'Queen of Cups', 'Esta carta combina um domínio interno, receptivo e consciente com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The Queen gazes quietly at a richly decorated cup. She seems to look into the depths of the heart, symbolizing deep empathy, intuition, and emotional receptivity.', 'Maturidade e presença permitem sustentar o tema com profundidade. Os sentimentos podem circular com mais honestidade e receptividade.', 'Embracing everything with compassion and intuition. The heart is gentle and able to understand and contain others'' emotions. This card suggests healing, empathy, intuition, and deep love.', 'Controle indireto, fechamento ou absorção excessiva drenam energia. Carências, idealizações ou emoções represadas pedem atenção.', 'Becoming so immersed in emotion that boundaries dissolve. Feelings may be too sensitive, making you vulnerable to others'' emotional influence. It can also suggest dependency, emotional volatility, or escape from reality.'),
  ('king-of-cups', 14, 'cups', 'Rei de Copas', 'King of Cups', 'Esta carta combina um domínio externo capaz de orientar e decidir com o campo de afetos, vínculos e vida emocional. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The King sits calmly on a throne floating above the sea, holding a cup and scepter. Although surrounded by waves, he remains composed, showing emotional maturity and mastery.', 'Experiência e responsabilidade dão direção ao que precisa avançar. Os sentimentos podem circular com mais honestidade e receptividade.', 'Holding emotional mastery while leading with compassion. Feelings run deep, yet they are managed calmly instead of becoming overwhelming. This card suggests mature love, tolerance, understanding, and emotional leadership.', 'Autoridade rígida ou necessidade de controle abafam outras perspectivas. Carências, idealizações ou emoções represadas pedem atenção.', 'Suppressing or controlling emotions in a way that creates imbalance. Feelings are held down or managed unhealthily. It can also suggest a calm exterior with inner turmoil, or using emotion to control others.'),
  ('ace-of-pentacles', 1, 'pentacles', 'Ás de Ouros', 'Ace of Pentacles', 'Esta carta combina um começo concentrado e cheio de potencial com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The pentacle held in the hand of God symbolizes abundance. Beyond the beautiful garden spreading below lies a steep mountain range. This card represents how consistent effort can lead to prosperity and a bountiful environment.', 'Uma semente está pronta para receber direção. Há potencial para construir segurança por meio de cuidado concreto.', 'Manifesting abundance through effort: You possess the definite power to realize your wishes. Your efforts so far will be rewarded. You may also gain wealth or recognition.', 'O impulso inicial pode ser desperdiçado ou reprimido. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Prioritizing profit over action: Suggests being fixated on profit while failing to take appropriate action. Additionally, there is a possibility that important networks built over time may collapse.'),
  ('two-of-pentacles', 2, 'pentacles', 'Dois de Ouros', 'Two of Pentacles', 'Esta carta combina uma escolha entre forças que buscam equilíbrio com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card depicts a juggler dancing while skillfully balancing two pentacles. It represents adaptability and flexibility-the ability to navigate any situation smoothly.', 'Comparar caminhos com presença favorece uma decisão mais íntegra. Há potencial para construir segurança por meio de cuidado concreto.', 'Assessing situations and responding appropriately: Handling matters at hand with flexibility. This shows that things are proceeding favorably with good momentum.', 'Indecisão ou polarização podem manter a situação suspensa. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Unable to adapt to circumstances: Struggling with new changes and feeling distressed. Also represents anxiety from not fitting in well with your surroundings.'),
  ('three-of-pentacles', 3, 'pentacles', 'Três de Ouros', 'Three of Pentacles', 'Esta carta combina crescimento que nasce do encontro e da expressão com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A sculptor stands on a platform, his craft recognized as he is entrusted with important work. This card indicates that your sustained effort and developing skills are gaining recognition and bringing new opportunities.', 'Colaboração e expansão tornam o movimento mais fértil. Há potencial para construir segurança por meio de cuidado concreto.', 'Your cultivated abilities gaining recognition: Your steady efforts have earned recognition from those around you. Also suggests that previously unknown talents are attracting attention.', 'Excesso, ruído ou falta de alinhamento podem dispersar resultados. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Abilities not receiving recognition: Despite your capabilities, you''re not gaining recognition. Or your skills may still need further development.'),
  ('four-of-pentacles', 4, 'pentacles', 'Quatro de Ouros', 'Four of Pentacles', 'Esta carta combina uma estrutura que oferece estabilidade e contenção com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A miser clutches pentacles tightly to his chest. The street scene behind him suggests his preoccupation with worldly wealth. This card depicts strong possessiveness and attachment to material things.', 'Consolidar o que funciona cria base para o próximo passo. Há potencial para construir segurança por meio de cuidado concreto.', 'Prioritizing stable security: Taking cautious action to avoid failure. While stable, it also reveals an obsessive attachment to possessions.', 'Controle e acomodação podem transformar segurança em estagnação. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Greed overtaking reason: Prioritizing profit leads to questionable decisions. Also represents stinginess with money.'),
  ('five-of-pentacles', 5, 'pentacles', 'Cinco de Ouros', 'Five of Pentacles', 'Esta carta combina uma tensão que revela perda, contraste ou necessidade de mudança com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'Two figures pass before a church, yet out of pride, neither seeks help there. This card represents the harshness and trials of survival.', 'O desconforto mostra com clareza o que precisa ser reorganizado. Há potencial para construir segurança por meio de cuidado concreto.', 'Spiritual emptiness from hardship: Showing a progressively worsening situation. Heavy-hearted from isolation and withdrawing inward. Expressing a sense of desperation that calls for redemption.', 'Fixar-se na falta pode impedir a percepção dos recursos restantes. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Recovering hope through support: Past hardships gradually improving. Someone extends help, lifting your spirits and renewing hope.'),
  ('six-of-pentacles', 6, 'pentacles', 'Seis de Ouros', 'Six of Pentacles', 'Esta carta combina um movimento de ajuste, troca e recomposição com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'This card depicts a person in power holding scales in one hand and bestowing gifts on others. It represents a relationship where both the giver and receiver are filled with goodwill and kindness.', 'Reciprocidade e transição consciente restauram o fluxo. Há potencial para construir segurança por meio de cuidado concreto.', 'Connection between giver and receiver: Based on the desire to ''give something to someone.'' Perhaps the other person is waiting for this generosity.', 'Desequilíbrio nas trocas ou apego ao passado atrasam a passagem. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Connection between controller and controlled: Expressing a desire to control others. Can also mean developing an urge to constrain someone you care about.'),
  ('seven-of-pentacles', 7, 'pentacles', 'Sete de Ouros', 'Seven of Pentacles', 'Esta carta combina um teste de discernimento, posicionamento e persistência com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A man looks worriedly at the harvested pentacle fruit. Despite considerable effort, the results are disappointing. This card suggests an obstacle that must be overcome to achieve growth.', 'Escolher com critério fortalece a direção já conquistada. Há potencial para construir segurança por meio de cuidado concreto.', 'Addressing issues to progress: Indicates the need for reassessment. Whether of your thoughts, plans, or craftsmanship-improvements can lead to advancement.', 'Defensividade, fantasia ou avaliação superficial confundem prioridades. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Proceeding with anxiety and inattention: Perhaps your self-assessment is inflated. Can also mean handling things carelessly or lacking passion and effort.'),
  ('eight-of-pentacles', 8, 'pentacles', 'Oito de Ouros', 'Eight of Pentacles', 'Esta carta combina uma fase de movimento, prática e reorganização com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A focused craftsman silently creates pentacles. The town behind him represents the day when his work will be recognized. This card shows the accumulation of dedicated effort.', 'Repetição consciente e foco aceleram o aprendizado. Há potencial para construir segurança por meio de cuidado concreto.', 'Focusing intently on your work: High concentration and dedication. Through focused effort toward your goals, you acquire solid skills and steadily progress toward success.', 'Automatismo, pressa ou aprisionamento mental estreitam possibilidades. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Unable to maintain focus: Various obstacles scatter your attention. May appear busy but potentially shirking real work.'),
  ('nine-of-pentacles', 9, 'pentacles', 'Nove de Ouros', 'Nine of Pentacles', 'Esta carta combina um estágio de maturidade, autonomia e quase conclusão com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'An elegant woman has tamed the falcon of wisdom, and the castle-like structure behind her symbolizes her elevated status. It represents achieving success through charm or talent.', 'A experiência acumulada permite reconhecer valor e suficiência. Há potencial para construir segurança por meio de cuidado concreto.', 'Success through recognition: Showing that success is achieved through support from those around you. Also comes with rewards such as independence or establishing yourself.', 'Isolamento, excesso de expectativa ou vigilância impedem descanso. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Achieving success through deception: Hints at attempting to gain success through fraud or dishonesty. May result in abandonment and isolation by others.'),
  ('ten-of-pentacles', 10, 'pentacles', 'Dez de Ouros', 'Ten of Pentacles', 'Esta carta combina a culminação de um ciclo e suas consequências com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card depicts a family living in wealth. The man in the center holds a magical wand-perhaps power inherited from the elderly man on the left. This card expresses inheritance and lasting prosperity.', 'O resultado pode ser integrado, compartilhado e transformado em legado. Há potencial para construir segurança por meio de cuidado concreto.', 'Maintaining prosperous stability through inheritance: Increasing wealth through inherited assets, gaining success from skills passed down by others, becoming progressively wealthier.', 'Sobrecarga ou apego ao resultado dificultam o encerramento necessário. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Inherited things reaching their limit: Inherited assets failing to deliver value or creating disputes, becoming liabilities instead.'),
  ('page-of-pentacles', 11, 'pentacles', 'Pajem de Ouros', 'Page of Pentacles', 'Esta carta combina uma curiosidade jovem que traz notícia, estudo e descoberta com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The young man gazes intently at the pentacle held in both hands, appearing dedicated to study and hard work. There is no need to hurry; by cultivating various skills, a bright future awaits.', 'Abertura para aprender renova a relação com o tema. Há potencial para construir segurança por meio de cuidado concreto.', 'Building through dedication: You are steadily working on something worthwhile right now. This card suggests that the effort you''re investing now will prove invaluable later.', 'Imaturidade ou informação incompleta pedem verificação antes de agir. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Wasting time: Shows that time is being spent unproductively. The pace may need to quicken or methods require improvement.'),
  ('knight-of-pentacles', 12, 'pentacles', 'Cavaleiro de Ouros', 'Knight of Pentacles', 'Esta carta combina uma força em movimento que persegue sua intenção com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The Knight of Pentacles sits upon a black horse in armor, gazing into the distance as if envisioning a successful future. This card expresses steadfast dedication and hard work.', 'Compromisso e ação colocam a energia do naipe em circulação. Há potencial para construir segurança por meio de cuidado concreto.', 'Persevering to the end: You appear capable of persisting with current tasks through to completion. Sometimes implies the need for perseverance and personal responsibility.', 'Pressa, insistência ou intensidade sem escuta podem criar desequilíbrio. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Stagnating by maintaining the status quo: Defensive posture too strong, preventing positive change. Your current work might unconsciously become mere habit.'),
  ('queen-of-pentacles', 13, 'pentacles', 'Rainha de Ouros', 'Queen of Pentacles', 'Esta carta combina um domínio interno, receptivo e consciente com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The Queen gazes calmly at the pentacle. The rabbit at her feet symbolizes abundance. This card depicts a nurturing, maternal heart that embraces all, bringing wealth and good fortune.', 'Maturidade e presença permitem sustentar o tema com profundidade. Há potencial para construir segurança por meio de cuidado concreto.', 'Growing through nurturing others: Finding joy in giving your effort to someone. This positively influences not just them but yourself, building strength.', 'Controle indireto, fechamento ou absorção excessiva drenam energia. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Indulgence only destroys both: Unconditional acceptance backfires. Your devoted care makes the other dependent, leading to mutual decline.'),
  ('king-of-pentacles', 14, 'pentacles', 'Rei de Ouros', 'King of Pentacles', 'Esta carta combina um domínio externo capaz de orientar e decidir com o campo de recursos, corpo, trabalho e realidade material. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The king sits serenely on his throne, pentacle in hand. The plants surrounding him symbolize the wealth in his possession. As a king, how to use his resources for the benefit of others is the essential question.', 'Experiência e responsabilidade dão direção ao que precisa avançar. Há potencial para construir segurança por meio de cuidado concreto.', 'Putting your strengths to work: Successfully utilizing your own capabilities. Wanting to help others through what you can do, or being in a position to do so.', 'Autoridade rígida ou necessidade de controle abafam outras perspectivas. Apego, escassez percebida ou rigidez material podem limitar escolhas.', 'Not utilizing your strengths well: Not fully leveraging your capabilities. Failing to flexibly use wealth or ability, unable to meet the expectations of those around you.'),
  ('ace-of-swords', 1, 'swords', 'Ás de Espadas', 'Ace of Swords', 'Esta carta combina um começo concentrado e cheio de potencial com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The hand of God holds a sword, and a crown symbolizing victory rests on its tip. The steep mountains in the background reveal that this is by no means an easy path. This card represents overcoming severe circumstances through strong mental power.', 'Uma semente está pronta para receber direção. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Opening new paths to achieve goals: You want to challenge yourself with new things. Even when facing unfamiliar territory, you approach it with a positive and adventurous spirit.', 'O impulso inicial pode ser desperdiçado ou reprimido. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Harsh attitudes leading to destruction: Acting with self-interest as the priority without considering the consequences. Spiraling toward self-destruction.'),
  ('two-of-swords', 2, 'swords', 'Dois de Espadas', 'Two of Swords', 'Esta carta combina uma escolha entre forças que buscam equilíbrio com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A woman holds two swords with both hands. Her blindfold may indicate something she does not want to face, or perhaps she wants to hide her true thoughts. The two swords suggest a state of inner conflict.', 'Comparar caminhos com presença favorece uma decisão mais íntegra. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Maintaining harmony with a calm heart: Face the problem before you without rushing to conclusions. By choosing the right moment, you can restore inner peace.', 'Indecisão ou polarização podem manter a situação suspensa. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Seeking quick fixes leads to a dead end: Avoiding the core of the problem and using temporary measures may result in failure. Previously resolved issues may resurface.'),
  ('three-of-swords', 3, 'swords', 'Três de Espadas', 'Three of Swords', 'Esta carta combina crescimento que nasce do encontro e da expressão com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A heart representing love is pierced by three swords and drenched in sorrowful rain. This card suggests a shocking event that deeply wounds the heart.', 'Colaboração e expansão tornam o movimento mais fértil. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Accepting the core of reality: Understanding the truth you did not want to know. Despite this unwelcome situation, you attempt to move forward.', 'Excesso, ruído ou falta de alinhamento podem dispersar resultados. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Rejecting truth and struggling in pain: Overwhelmed by a shocking event. Unable to accept the reality before you, your suffering may be prolonged.'),
  ('four-of-swords', 4, 'swords', 'Quatro de Espadas', 'Four of Swords', 'Esta carta combina uma estrutura que oferece estabilidade e contenção com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A knight statue lies with closed eyes, hands joined on the chest as if in prayer. This card expresses quiet rest and solitude.', 'Consolidar o que funciona cria base para o próximo passo. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Quiet rest and regrouping: The upright position expresses "resting." Things tend to slow down. However, during this period you also gain time for reflection.', 'Controle e acomodação podem transformar segurança em estagnação. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Preparing to start again: The reversed position indicates "recovery is complete." Rest has ended, you are awakening, and moving toward a fresh start.'),
  ('five-of-swords', 5, 'swords', 'Cinco de Espadas', 'Five of Swords', 'Esta carta combina uma tensão que revela perda, contraste ou necessidade de mudança com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A man holding swords looks at two defeated people. A dispute seems to have taken place, and his grinning posture with the ominous clouds presents a hollow victory.', 'O desconforto mostra com clareza o que precisa ser reorganizado. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Seizing victory by any means: Expressing determination to achieve your goals no matter what. You won''t hesitate to use tactics and are highly cunning and strategic.', 'Fixar-se na falta pode impedir a percepção dos recursos restantes. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Important things being taken away: Due to unexpected traps or accidents, important things are lost. The cause may be your own inadequate ability or carelessness.'),
  ('six-of-swords', 6, 'swords', 'Seis de Espadas', 'Six of Swords', 'Esta carta combina um movimento de ajuste, troca e recomposição com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A man rows a boat while a mother and child sit in front of him. Perhaps they lower their heads and hide their faces because they have abandoned everything and fled. The card shows drifting with the current toward a new place.', 'Reciprocidade e transição consciente restauram o fluxo. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Escaping difficult circumstances: Gradually breaking free from hardship. The boat symbolizes travel or moving to a new location, representing transition and change.', 'Desequilíbrio nas trocas ou apego ao passado atrasam a passagem. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Falling back into old difficulties: Suggesting inability to escape hardship or returning to an environment you thought you had already left.'),
  ('seven-of-swords', 7, 'swords', 'Sete de Espadas', 'Seven of Swords', 'Esta carta combina um teste de discernimento, posicionamento e persistência com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card depicts a man looking back while carrying swords and trying to flee. There are figures in the distance, but they do not seem to have noticed him yet. This card suggests illegality or injustice.', 'Escolher com critério fortalece a direção já conquistada. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Planning deceit in the shadows: Plotting tricks without letting anyone discover. Sometimes it can be interpreted as avoiding responsibility and acting in self-interest. This is a card of calculated risk.', 'Defensividade, fantasia ou avaliação superficial confundem prioridades. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Sensing danger and making thorough preparations: Recognizing the malice of others and heightening vigilance. Thorough preparation is effective, and things will proceed safely. Can also mean assisting others.'),
  ('eight-of-swords', 8, 'swords', 'Oito de Espadas', 'Eight of Swords', 'Esta carta combina uma fase de movimento, prática e reorganização com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A blindfolded and bound woman is surrounded by swords. Looking closely, there are no guards, and her feet can move. This card suggests that what is bound is not the body, but the heart.', 'Repetição consciente e foco aceleram o aprendizado. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Waiting for rescue in painful circumstances: Harboring the thought that you lack power and hoping others will rescue you. The person is suffering from powerlessness and loneliness, seemingly unable to move.', 'Automatismo, pressa ou aprisionamento mental estreitam possibilidades. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Struggling without support: In an isolated state, feeling anxious. Thinking this shouldn''t be the case, resisting while harboring strong victim consciousness, blaming others.'),
  ('nine-of-swords', 9, 'swords', 'Nove de Espadas', 'Nine of Swords', 'Esta carta combina um estágio de maturidade, autonomia e quase conclusão com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A woman sits on a bed sighing. Perhaps she had a nightmare, or cried all night out of despair. This card presents sorrow, anxiety, and guilt, while also suggesting awakening from this state.', 'A experiência acumulada permite reconhecer valor e suficiência. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Hopelessness that cannot be undone: Showing strong regret, continuously thinking "if only I had done this differently," blaming yourself and unable to see what''s around you.', 'Isolamento, excesso de expectativa ou vigilância impedem descanso. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Unwilling to face a bad situation: Turning away from reality, unwilling to face the essence of the problem. Only blaming others, pretending it didn''t happen, or feeling sorry for yourself.'),
  ('ten-of-swords', 10, 'swords', 'Dez de Espadas', 'Ten of Swords', 'Esta carta combina a culminação de um ciclo e suas consequências com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A man lies with ten swords piercing his body. The image seems ominous at first glance, but if you look closely, the dark sky is about to clear. This card shows gaining a bright future by accepting reality.', 'O resultado pode ser integrado, compartilhado e transformado em legado. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Moving forward after accepting everything: A state of completely accepting your weaknesses or present circumstances, which can be called enlightenment. As a result, you move to the next stage.', 'Sobrecarga ou apego ao resultado dificultam o encerramento necessário. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Only looking at what is favorable to you: Not psychologically prepared and unable to accept things that are unfavorable. As a result, you remain trapped in the fantasy world.'),
  ('page-of-swords', 11, 'swords', 'Pajem de Espadas', 'Page of Swords', 'Esta carta combina uma curiosidade jovem que traz notícia, estudo e descoberta com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A youth holds a sword and looks back with a sharp gaze. The flock of birds flying overhead expresses his high mental power. This card shows the caution and analytical ability needed to respond even to an explosive situation.', 'Abertura para aprender renova a relação com o tema. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Seeing the situation clearly and being cautious: Observing your surroundings attentively, sometimes indicating the need to proceed with something secretly. Crisis awareness is very high.', 'Imaturidade ou informação incompleta pedem verificação antes de agir. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Caution appearing somewhat lax: Though having a sense of caution, it highlights inadequate defense. For instance, carelessly revealing information or saying something indiscreet. Important things may be lost due to carelessness.'),
  ('knight-of-swords', 12, 'swords', 'Cavaleiro de Espadas', 'Knight of Swords', 'Esta carta combina uma força em movimento que persegue sua intenção com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The knight rides a white horse, his gaze fixed straight ahead. The sword he raises is an expression of his will and confidence. It symbolizes charging forward without hesitation, with inner strength and courage.', 'Compromisso e ação colocam a energia do naipe em circulação. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Making a firm decision and moving forward logically: Not spending unnecessary effort, attempting to dash toward your goal via the shortest route. Making judgments that are rational, not swayed by emotion.', 'Pressa, insistência ou intensidade sem escuta podem criar desequilíbrio. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Causing unnecessary disputes: Rather than attacking, it''s more a provocation, causing unnecessary troubles. There seems to be a desire to take credit hastily.'),
  ('queen-of-swords', 13, 'swords', 'Rainha de Espadas', 'Queen of Swords', 'Esta carta combina um domínio interno, receptivo e consciente com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The Queen sits on her throne, staring ahead without blinking. The sword in her right hand points toward the sky, while her left hand seems ready to accept all faults. This card has both strictness and gentleness.', 'Maturidade e presença permitem sustentar o tema com profundidade. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Earning admiration through correct words and actions: When believing something "should be done this way," implementing it without hesitation. Not being arrogant, considering others'' circumstances when speaking, thus earning approval.', 'Controle indireto, fechamento ou absorção excessiva drenam energia. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Arming oneself for self-defense: Using sharp intellect only to protect yourself. Attacking without mercy those things that harm you, being very cold about human feelings.'),
  ('king-of-swords', 14, 'swords', 'Rei de Espadas', 'King of Swords', 'Esta carta combina um domínio externo capaz de orientar e decidir com o campo de pensamento, comunicação, conflito e discernimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The King faces forward with a severe expression. From his many battles up to now, he believes himself to be correct. The sword in his hand expresses a strict attitude that does not allow pleading or perfunctory treatment.', 'Experiência e responsabilidade dão direção ao que precisa avançar. Clareza mental e conversas diretas ajudam a cortar a confusão.', 'Making judgments through objective analysis: In any situation, seeing the circumstances clearly and making appropriate judgments. Always demanding of yourself to remain fair, not self-serving.', 'Autoridade rígida ou necessidade de controle abafam outras perspectivas. Ansiedade, dureza ou narrativas repetitivas podem ampliar o conflito.', 'Authoritarily guarding dignity: A state where possessed wisdom is only used to protect oneself. Even cruelly eliminating those who don''t comply with wishes, not admitting one''s own faults.'),
  ('ace-of-wands', 1, 'wands', 'Ás de Paus', 'Ace of Wands', 'Esta carta combina um começo concentrado e cheio de potencial com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The Ace of Wands shows the hand of God holding a wand, the symbol of life force. The castle-like structure in the background represents your aspirational goal. This card conveys fierce passion and the drive to seize what you desire.', 'Uma semente está pronta para receber direção. A energia disponível favorece expressão, coragem e ação consciente.', 'Taking on a new challenge. Power is rising, a new goal is emerging, and you are ready to move forward to grow.', 'O impulso inicial pode ser desperdiçado ou reprimido. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'A challenge is winding down. Passion is fading, and matters are gradually coming to a close. Alternatively, it can indicate power spiraling out of control.'),
  ('two-of-wands', 2, 'wands', 'Dois de Paus', 'Two of Wands', 'Esta carta combina uma escolha entre forças que buscam equilíbrio com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The figure stands atop a castle, holding a small globe with the bearing of one who has succeeded. Although glory has already been achieved, dissatisfaction lingers and new ambitions emerge. This card shows the will to reach even higher.', 'Comparar caminhos com presença favorece uma decisão mais íntegra. A energia disponível favorece expressão, coragem e ação consciente.', 'Recognizing your accomplishments and growth, and using that confidence as a foundation for new ambitions to reach higher.', 'Indecisão ou polarização podem manter a situação suspensa. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'You may lose something you have already gained, be displaced from your position, or watch what you earned through effort begin to fade.'),
  ('three-of-wands', 3, 'wands', 'Três de Paus', 'Three of Wands', 'Esta carta combina crescimento que nasce do encontro e da expressão com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'A man on a cliff gazes out over the sea. Is he watching ships depart, or waiting for them to return? This card shows the state of contemplating your current situation and where to go next.', 'Colaboração e expansão tornam o movimento mais fértil. A energia disponível favorece expressão, coragem e ação consciente.', 'Catching a glimpse of opportunity to challenge. Your decision to move to a higher stage has taken shape, and only one final push is needed. The timing for action is drawing near.', 'Excesso, ruído ou falta de alinhamento podem dispersar resultados. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Anticipation fades while you hesitate. Although you are mentally and physically prepared, without someone to give that final push, you remain idle. It suggests that the expected notice has not arrived.'),
  ('four-of-wands', 4, 'wands', 'Quatro de Paus', 'Four of Wands', 'Esta carta combina uma estrutura que oferece estabilidade e contenção com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'People can be seen waving bouquets beyond the wands. Everyone lives in a relaxed and peaceful manner, and the castle behind them is a symbol of abundance. This card conveys stable happiness and joy.', 'Consolidar o que funciona cria base para o próximo passo. A energia disponível favorece expressão, coragem e ação consciente.', 'Gaining genuine joy from what you have truly pursued. It suggests freedom from obstacles, achieving stability and peace, and deeply recognizing that this is truly what you have been seeking.', 'Controle e acomodação podem transformar segurança em estagnação. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Seeking joy within your present circumstances. Giving up the pursuit of new gains and finding happiness in your current environment. Also reveals a state of passively accepting things.'),
  ('five-of-wands', 5, 'wands', 'Cinco de Paus', 'Five of Wands', 'Esta carta combina uma tensão que revela perda, contraste ou necessidade de mudança com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'Under a blue sky, five people proudly engage in battle. The bright colors of the card show that this conflict carries no negative emotion. This card speaks of competitive spirit, determination, and the drive to test yourself through victory or defeat.', 'O desconforto mostra com clareza o que precisa ser reorganizado. A energia disponível favorece expressão, coragem e ação consciente.', 'Striving through challenge and self-refinement. Though competitive spirit runs high, there is no malice here. You are trying to reach a certain goal through effort, contest, and determination.', 'Fixar-se na falta pode impedir a percepção dos recursos restantes. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Defeating one''s opponent. Entering a combative stance to wound and push away the other person. A willingness to fight to the end to make the opponent yield is evident.'),
  ('six-of-wands', 6, 'wands', 'Seis de Paus', 'Six of Wands', 'Esta carta combina um movimento de ajuste, troca e recomposição com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card shows a man holding the wand of victory, seated on a horse and moving forward slowly. From the fact that he leads an army, we can tell he must be an excellent commander. This card presents grasping glory and gaining happiness.', 'Reciprocidade e transição consciente restauram o fluxo. A energia disponível favorece expressão, coragem e ação consciente.', 'Proud to receive strong praise. Gaining recognition and feeling genuinely happy. Holding a sense of slight superiority and taking pride in successful outcomes.', 'Desequilíbrio nas trocas ou apego ao passado atrasam a passagem. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Dissatisfaction with unjust results. Feeling that you did far more, harboring hidden discontent. Even becoming irritable about praise from others, unable to feel genuinely happy.'),
  ('seven-of-wands', 7, 'wands', 'Sete de Paus', 'Seven of Wands', 'Esta carta combina um teste de discernimento, posicionamento e persistência com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card depicts a man fighting alone. From the number of wands stabbing upward, there are many enemies, but he has taken the advantageous position on the cliff. This card shows standing in an overwhelming advantage without wavering.', 'Escolher com critério fortalece a direção já conquistada. A energia disponível favorece expressão, coragem e ação consciente.', 'Winning from a favorable position. Standing in an advantageous position while controlling the situation. When luck is favorable, everything feels aligned in your favor.', 'Defensividade, fantasia ou avaliação superficial confundem prioridades. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Facing hardship in an unfavorable situation. This card hints at a severe predicament. You will be forced to face battle or challenge in an overwhelmingly disadvantageous position, sometimes suggesting mental confusion.'),
  ('eight-of-wands', 8, 'wands', 'Oito de Paus', 'Eight of Wands', 'Esta carta combina uma fase de movimento, prática e reorganização com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The eight wands move forward like arrows, symbolizing powerful force and speed. Their tips all face the same direction, suggesting that will and action are aligned and moving forward without hesitation.', 'Repetição consciente e foco aceleram o aprendizado. A energia disponível favorece expressão, coragem e ação consciente.', 'Moving forward at a dizzying speed. Things are suddenly in motion, indicating that circumstances will change at an unpredictable pace. Sometimes it can also be interpreted as something hoped for coming true.', 'Automatismo, pressa ou aprisionamento mental estreitam possibilidades. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Unexpected stalling. Things that were progressing smoothly suddenly stopped. Suggests a standstill caused by unforeseen problems, creating an impatient sense of closure.'),
  ('nine-of-wands', 9, 'wands', 'Nove de Paus', 'Nine of Wands', 'Esta carta combina um estágio de maturidade, autonomia e quase conclusão com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card shows a cautious man standing guard. Though wounded, he still prepares to fight, revealing an indomitable spirit that refuses to give in. This card asks what you are truly fighting for.', 'A experiência acumulada permite reconhecer valor e suficiência. A energia disponível favorece expressão, coragem e ação consciente.', 'Prepared to handle any situation. You have made thorough preparations and are on guard, with both body and mind full of tension.', 'Isolamento, excesso de expectativa ou vigilância impedem descanso. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Struck hard due to pride. You are too optimistic about the situation. The reversal hints that you cannot handle sudden circumstances, creating confusion. Sometimes it warns you of lacking self-awareness.'),
  ('ten-of-wands', 10, 'wands', 'Dez de Paus', 'Ten of Wands', 'Esta carta combina a culminação de um ciclo e suas consequências com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card shows a man carrying many wands in his arms, and from his posture one can even feel an attachment that says, "I absolutely will not let go." This card presents a choice: what should be held onto, and what should be released.', 'O resultado pode ser integrado, compartilhado e transformado em legado. A energia disponível favorece expressão, coragem e ação consciente.', 'Exhausting yourself under the weight of your own choices. Unable to set down the burden even though already exhausted. This card shows being overwhelmed by something only you can bear.', 'Sobrecarga ou apego ao resultado dificultam o encerramento necessário. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Putting down what has been pushing you. You have reached your limit. You seem to wish to release the burden and find relief. Sometimes it can be interpreted as lacking sense of responsibility.'),
  ('page-of-wands', 11, 'wands', 'Pajem de Paus', 'Page of Wands', 'Esta carta combina uma curiosidade jovem que traz notícia, estudo e descoberta com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card shows a boy responsible for delivering messages. From the way he looks up at a wand taller than himself, you can feel his openness and sincerity. It embodies a pure hope for the future and the passion to bring it to life.', 'Abertura para aprender renova a relação com o tema. A energia disponível favorece expressão, coragem e ação consciente.', 'Burning with passion while believing in the future. You look ahead with clear, honest eyes and approach your wishes with sincerity and openness. It suggests steady progress toward your dreams.', 'Imaturidade ou informação incompleta pedem verificação antes de agir. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Boasting with self-satisfaction. Behind talk of hope, a rebellious spirit and capricious attitude lurk. Sometimes it can mean acting with a rebellious heart against others without self-awareness.'),
  ('knight-of-wands', 12, 'wands', 'Cavaleiro de Paus', 'Knight of Wands', 'Esta carta combina uma força em movimento que persegue sua intenção com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'The card shows a brave young man riding a leaping horse. Although lively and full of charm, he is very difficult to rein in. This is a card of passion and strong impulses that are hard to contain.', 'Compromisso e ação colocam a energia do naipe em circulação. A energia disponível favorece expressão, coragem e ação consciente.', 'Setting out toward new horizons. A state where your heart feels delighted about the new beginning. Full of enthusiasm for challenge, suggesting active and immediate action.', 'Pressa, insistência ou intensidade sem escuta podem criar desequilíbrio. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Inner feelings unable to catch up with change. Unexpected change leaves you confused. Wanting to protect your original ground, you may thus take an offensive stance.'),
  ('queen-of-wands', 13, 'wands', 'Rainha de Paus', 'Queen of Wands', 'Esta carta combina um domínio interno, receptivo e consciente com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'This card depicts a woman holding a wand and a sunflower. Her boldly open posture suggests sexual charm, while the black cat at her feet hints at her mysterious, magical nature. This card displays strength that is fully aligned inside and out.', 'Maturidade e presença permitem sustentar o tema com profundidade. A energia disponível favorece expressão, coragem e ação consciente.', 'Those around you are naturally drawn in. It suggests becoming the center of attention. Because you are inwardly composed, you act with genuine warmth and generosity. It can also simply mean being openly admired.', 'Controle indireto, fechamento ou absorção excessiva drenam energia. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Self-righteous behavior causes misunderstanding. What you consider good works in a negative direction. Also shows the possibility of becoming the target of jealousy or misunderstanding.'),
  ('king-of-wands', 14, 'wands', 'Rei de Paus', 'King of Wands', 'Esta carta combina um domínio externo capaz de orientar e decidir com o campo de desejo, criatividade, iniciativa e movimento. Observe como essa dinâmica conversa com a posição que ela ocupa na tiragem.', 'This card shows a king holding a wand, always prepared to stand up. His posture expresses action and leadership, while the salamander at his feet symbolizes passion and power.', 'Experiência e responsabilidade dão direção ao que precisa avançar. A energia disponível favorece expressão, coragem e ação consciente.', 'Achieving things through conviction. This is a time when great power fills you from within. By turning those around you into allies, you can produce results no matter what difficulty appears.', 'Autoridade rígida ou necessidade de controle abafam outras perspectivas. Impulsividade, dispersão ou esgotamento podem desviar a força criativa.', 'Trying to control everything too forcefully. The determination to achieve your goals at any cost can also become the source of criticism. Sometimes it points to losing sound judgment because passion has become excessive.');

insert into public.spreads (
  id,
  display_order,
  name_pt_br,
  name_en,
  short_description_pt_br,
  short_description_en,
  description_pt_br,
  description_en,
  use_case_pt_br,
  use_case_en,
  position_count,
  active
)
values
  ('mandala', 1, 'Mandálica', 'Mandala', 'Panorama amplo da vida em sete dimensões.', 'A broad view of life across seven dimensions.', 'Uma leitura geral que conecta missão, corpo, mente, trabalho, relações, espiritualidade e tendências futuras.', 'A general reading connecting mission, body, mind, work, relationships, spirituality, and future trends.', 'Ideal para ciclos de transição e visões de médio prazo.', 'Best for transitions and medium-term perspectives.', 7, true),
  ('celtic-cross', 2, 'Cruz Celta', 'Celtic Cross', 'Uma análise profunda de uma situação complexa.', 'A deep analysis of a complex situation.', 'Dez posições revelam influências conhecidas, aspectos ocultos, ambiente e a tendência de desfecho.', 'Ten positions reveal known influences, hidden aspects, environment, and the likely outcome.', 'Ideal para perguntas importantes com muitas camadas.', 'Best for important questions with many layers.', 10, true),
  ('peladan', 3, 'Peladan', 'Peladan', 'Cinco perspectivas para uma pergunta específica.', 'Five perspectives for a specific question.', 'Uma cruz equilibrada entre forças favoráveis, ausências, caminho, resultado e síntese.', 'A balanced cross of favorable forces, absences, path, outcome, and synthesis.', 'Ideal para questões objetivas e delimitadas no tempo.', 'Best for objective, time-bound questions.', 5, true),
  ('three-balance', 4, 'Três Cartas · Balanço', 'Three Cards · Balance', 'Positivo, desafio e resultado em uma visão rápida.', 'Positive, challenge, and result at a glance.', 'Uma leitura concisa para identificar o que favorece, o que tensiona e a direção provável.', 'A concise reading to identify what supports, what challenges, and the likely direction.', 'Ideal para relações, carreira e decisões cotidianas.', 'Best for relationships, career, and daily decisions.', 3, true),
  ('three-time', 5, 'Três Cartas · Tempo', 'Three Cards · Time', 'Passado, presente e futuro de uma questão.', 'Past, present, and future of a question.', 'Uma linha temporal simples para compreender origens, momento atual e tendência.', 'A simple timeline for understanding origins, the current moment, and the trend ahead.', 'Ideal para observar a evolução de uma situação.', 'Best for observing how a situation evolves.', 3, true),
  ('advice', 6, 'Carta Conselho', 'Advice Card', 'Uma única carta para iluminar o momento.', 'One card to illuminate the moment.', 'Uma leitura breve para perceber fatores ocultos e conectar-se com a energia do dia, semana ou mês.', 'A brief reading to notice hidden factors and connect with the energy of the day, week, or month.', 'Ideal para reflexão diária e perguntas abertas.', 'Best for daily reflection and open questions.', 1, true),
  ('aphrodite', 7, 'Templo de Afrodite', 'Temple of Aphrodite', 'Dinâmica afetiva entre duas pessoas.', 'The emotional dynamics between two people.', 'Compara pensamentos, sentimentos e atração de cada pessoa, concluindo com uma síntese da relação.', 'Compares thoughts, feelings, and attraction for each person, ending with a relationship synthesis.', 'Ideal para compreender relações e vínculos afetivos.', 'Best for understanding emotional bonds.', 7, true),
  ('goals', 8, 'Alcance de Metas', 'Goal Achievement', 'Estratégia para objetivos profissionais e pessoais.', 'A strategy for professional and personal goals.', 'Sete posições mapeiam situação, meta, bloqueios, primeiros passos, apoios, crenças e o elemento-chave.', 'Seven positions map the situation, goal, obstacles, first steps, support, beliefs, and key element.', 'Ideal para carreira, finanças e projetos pessoais.', 'Best for career, finances, and personal projects.', 7, true);

